  load=provider??SupportActions.LoadSettings;persist=saver??SupportActions.SaveSettings;startup=startupSaver??SupportActions.SetAutoStartEnabled;Dock=DockStyle.Fill;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;
