  permanentPasswordBox.UseSystemPasswordChar=true;var reveal=WorkspaceUi.Button("Show",()=>permanentPasswordBox.UseSystemPasswordChar=!permanentPasswordBox.UseSystemPasswordChar);reveal.Leave+=(s,e)=>permanentPasswordBox.UseSystemPasswordChar=true;
  var security=Page("Security","Receiving access for THIS computer.");WorkspaceUi.Add(security,WorkspaceUi.Card("Permanent password",WorkspaceUi.Text("Leave empty for a fresh OTP on app launch or saved reconfiguration.",true),WorkspaceUi.Field("Password for this computer",WorkspaceUi.Pair(permanentPasswordBox,reveal)),WorkspaceUi.Button("Clear password",()=>{permanentPasswordBox.Clear();saveStatus.Text="Password cleared in the draft. Save changes to apply; Discard restores it.";})));pages[1]=security;
