 static TableLayoutPanel Page(string title,string text){var page=WorkspaceUi.Stack();WorkspaceUi.Add(page,WorkspaceUi.Text(title,false,18));WorkspaceUi.Add(page,WorkspaceUi.Text(text,true));return page;}
 internal void SelectCategory(int index){Category=index;for(int i=0;i<4;i++){pages[i].Visible=i==index;categories[i].Checked=i==index;}pages[index].BringToFront();Appearance.Apply(CategoryPanel);}
 internal void Reload(bool discarded=false){try{var settings=load();relayHostBox.Text=settings.RelayHost;relayPortBox.Text=settings.RelayPort.ToString();relayPinBox.Text=settings.RelayPin;permanentPasswordBox.Text=settings.PermanentPassword;autoStartBox.Checked=settings.AutoStartEnabled;lanEnabled.Checked=settings.LanEnabled;lanAddress.Text=settings.LanAddress;lanPort.Text=settings.LanPort.ToString();saveStatus.Text=discarded?"Draft discarded. No settings were changed.":"Changes are staged. Save to apply.";}catch(Exception ex){saveStatus.Text="Settings unavailable: "+ex.Message;}}
 RemsupSettings ReadDraft(){var existing=load();int port,local;var relay=RelayConfiguration.Parse(new[]{"RelayHost="+relayHostBox.Text,"RelayPort="+relayPortBox.Text});port=relay.Port;local=int.TryParse(lanPort.Text,out local)?local:0;return new RemsupSettings{AllowScreenView=existing.AllowScreenView,AllowScreenControl=existing.AllowScreenControl,AutoAcceptScreenSessions=existing.AutoAcceptScreenSessions,RelayHost=relay.Host,RelayPort=port,RelayPin=relayPinBox.Text.Trim(),LanEnabled=lanEnabled.Checked,LanAddress=lanAddress.Text.Trim(),LanPort=local,AutoStartEnabled=autoStartBox.Checked,PermanentPassword=permanentPasswordBox.Text};}
 internal bool SaveDraft(){try{return SaveValues(ReadDraft());}catch(Exception ex){saveStatus.Text="Settings could not be saved: "+ex.Message;return false;}}
 internal bool SaveValues(RemsupSettings settings){
  try{var relay=new RelayConfiguration(settings.RelayHost,settings.RelayPort,settings.RelayPin).Validated();settings.RelayHost=relay.Host;settings.RelayPort=relay.Port;settings.RelayPin=relay.Pin;
   if(settings.LanEnabled){IPAddress address;if(!IPAddress.TryParse(settings.LanAddress,out address)||!SupportHost.PrivateAddress(address)||settings.LanPort<1||settings.LanPort>65535)throw new ArgumentException("Enter this computer's Private IPv4 and LAN port 1–65535.");}
   if(!string.IsNullOrEmpty(settings.PermanentPassword))RemsupProtocol.ValidateCredentials("111222333",settings.PermanentPassword);
   persist(settings);startup(settings.AutoStartEnabled);var saved=SettingsSaved;if(saved!=null)saved();saveStatus.Text="Settings saved. Checking support readiness…";return true;
  }catch(Exception ex){saveStatus.Text="Settings could not be saved/applied: "+ex.Message;saveStatus.AccessibleDescription=saveStatus.Text;return false;}
 }
 void Firewall(bool remove){try{IPAddress ip;int port;if(!IPAddress.TryParse(lanAddress.Text,out ip)||!SupportHost.LocalPrivateAddress(ip)||!int.TryParse(lanPort.Text,out port)||port<1||port>65535)throw new ArgumentException("Choose this computer's active Private IPv4 and LAN port.");if(MessageBox.Show(this,(remove?"Remove":"Prepare")+" this app's scoped Private/local-subnet firewall rule? Visible UAC is required.","LAN firewall",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;var settings=load();settings.LanAddress=ip.ToString();settings.LanPort=port;persist(settings);SupportActions.RunElevatedHelper(remove?"--helper-lan-remove":"--helper-lan-firewall");saveStatus.Text="Firewall action completed. Save to apply the draft LAN choice.";}catch(Exception ex){saveStatus.Text="Firewall action failed: "+ex.Message;}}
